import numpy as np
import pandas as pd
from sklearn.preprocessing import SplineTransformer

_CUT_MAP = {'Fair': 1.0, 'Good': 2.0, 'Very Good': 3.0, 'Premium': 4.0, 'Ideal': 5.0}
_COLOR_MAP = {'J': 1.0, 'I': 2.0, 'H': 3.0, 'G': 4.0, 'F': 5.0, 'E': 6.0, 'D': 7.0}
_CLARITY_MAP = {'I1': 1.0, 'SI2': 2.0, 'SI1': 3.0, 'VS2': 4.0, 'VS1': 5.0, 'VVS2': 6.0, 'VVS1': 7.0, 'IF': 8.0}


def _num(s):
    return pd.to_numeric(s, errors='coerce').to_numpy(dtype=float)


def _map(s, m):
    return s.astype(str).str.strip().map(m).fillna(0.0).to_numpy(dtype=float)


class CaratSplineQuality:
    def __init__(self, config=None):
        cfg = dict(config or {})
        self.n_knots = int(cfg.get('n_knots', 10))
        self.degree = int(cfg.get('degree', 3))
        self.thresholds = tuple(float(t) for t in cfg.get('thresholds', (0.5, 0.7, 0.9, 1.0, 1.25, 1.5, 2.0)))
        self.spline_ = None
        self.carat_fill_ = 1.0
        self.carat_lo_ = 0.2
        self.carat_hi_ = 5.0
        self.stats_ = {}
        self.mu_ = None
        self.sd_ = None
        self.columns_ = None

    def _carat(self, X):
        c = _num(X['carat'])
        c = np.where(np.isfinite(c), c, self.carat_fill_)
        return np.clip(c, self.carat_lo_, self.carat_hi_)

    def fit_transform(self, X, y=None, context=None):
        c_raw = _num(X['carat'])
        finite = c_raw[np.isfinite(c_raw)]
        self.carat_fill_ = float(np.median(finite)) if finite.size else 1.0
        c = np.where(np.isfinite(c_raw), c_raw, self.carat_fill_)
        lo = float(np.min(c))
        hi = float(np.max(c))
        if (not np.isfinite(lo)) or (not np.isfinite(hi)) or (hi <= lo):
            lo, hi = 0.2, 5.01
        self.carat_lo_, self.carat_hi_ = lo, hi
        c = np.clip(c, lo, hi)
        self.spline_ = SplineTransformer(
            n_knots=self.n_knots,
            degree=self.degree,
            knots='quantile',
            include_bias=False,
            extrapolation='constant',
        )
        basis = self.spline_.fit_transform(c.reshape(-1, 1))
        for name, arr in (
            ('clarity', _map(X['clarity'], _CLARITY_MAP)),
            ('color', _map(X['color'], _COLOR_MAP)),
            ('cut', _map(X['cut'], _CUT_MAP)),
        ):
            mu = float(np.mean(arr))
            sd = float(np.std(arr))
            if (not np.isfinite(sd)) or sd < 1e-9:
                sd = 1.0
            self.stats_[name] = (mu, sd)
        out = self._assemble(X, basis)
        arr = out.to_numpy(dtype=float)
        self.mu_ = arr.mean(axis=0)
        sd = arr.std(axis=0)
        sd = np.where(np.isfinite(sd) & (sd > 1e-9), sd, 1.0)
        self.sd_ = sd
        self.columns_ = list(out.columns)
        z = (arr - self.mu_) / self.sd_
        return pd.DataFrame(z, columns=self.columns_, index=X.index)

    def transform(self, X):
        c = self._carat(X)
        basis = self.spline_.transform(c.reshape(-1, 1))
        out = self._assemble(X, basis)
        arr = out.to_numpy(dtype=float)
        arr = (arr - self.mu_) / self.sd_
        return pd.DataFrame(arr, columns=self.columns_, index=X.index)

    def _assemble(self, X, basis):
        c = self._carat(X)
        zs = {}
        for name in ('clarity', 'color', 'cut'):
            arr = _map(X[name], {'clarity': _CLARITY_MAP, 'color': _COLOR_MAP, 'cut': _CUT_MAP}[name])
            mu, sd = self.stats_.get(name, (float(np.mean(arr)), 1.0))
            zs[name] = (arr - mu) / sd
        data = {}
        k = basis.shape[1]
        for i in range(k):
            data['cs_%d' % i] = basis[:, i]
        for name in ('clarity', 'color', 'cut'):
            for i in range(k):
                data['cs_%s_%d' % (name, i)] = basis[:, i] * zs[name]
        for t in self.thresholds:
            tag = ('%g' % t).replace('.', 'p')
            data['carat_ge_%s' % tag] = (c >= t - 1e-9).astype(float)
        out = pd.DataFrame(data, index=X.index)
        out = out.replace([np.inf, -np.inf], np.nan).fillna(0.0)
        return out


def create_features(config=None):
    return CaratSplineQuality(config)

