from pathlib import Path

import cloudpickle
import numpy as np
from sklearn.linear_model import Ridge


class Candidate:
    """Estimator-only Ridge baseline.

    The SDK supplies already transformed X/validation_X per preprocessing_spec
    (dense float64 array). This candidate only fits Ridge on that representation.
    """

    def __init__(self, config):
        config = config or {}
        self.params = dict(config.get('model_params', {}) or {})
        self.model = None

    def _params(self, context):
        params = dict(self.params)
        # Consume all declared model params; search-space params are supplied by runner.
        alpha = params.pop('alpha', 1.0)
        fit_intercept = params.pop('fit_intercept', True)
        solver = params.pop('solver', 'auto')
        kwargs = {}
        if params:
            kwargs.update(params)
        return dict(alpha=alpha, fit_intercept=fit_intercept, solver=solver, **kwargs)

    def fit(self, X, y, context):
        params = self._params(context)
        params['random_state'] = 0  # Ridge accepts random_state for some solvers
        try:
            model = Ridge(**params)
        except TypeError:
            params.pop('random_state', None)
            model = Ridge(**params)

        if context.sample_weight is not None:
            model.fit(X, y, sample_weight=context.sample_weight)
        else:
            model.fit(X, y)
        self.model = model
        return self

    def predict(self, X, prediction_spec=None):
        return np.asarray(self.model.predict(X)).ravel()

    def export_model_params(self):
        return dict(self.params)

    def save(self, artifact_dir):
        artifact_dir = Path(artifact_dir)
        artifact_dir.mkdir(parents=True, exist_ok=True)
        (artifact_dir / 'candidate.pkl').write_bytes(cloudpickle.dumps(self))


def create_candidate(config):
    return Candidate(config)


def load_candidate(artifact_dir):
    return cloudpickle.loads((Path(artifact_dir) / 'candidate.pkl').read_bytes())

