import numpy as np
import pandas as pd
from sklearn.preprocessing import OneHotEncoder

_EXPECTED_COLUMNS = ['carat', 'cut', 'color', 'clarity', 'depth', 'table', 'x', 'y', 'z']
_NUMERIC_BASE = ['carat', 'depth', 'table', 'x', 'y', 'z']
_NUMERIC_MODEL = ['carat', 'depth', 'table', 'x', 'y', 'z', 'carat_power_2', 'carat_power_3']
_CATEGORICAL = ['cut', 'color', 'clarity']
_MISSING_CATEGORY = '__MLMOM_MISSING__'

class Preprocessor:
    def __init__(self, config=None):
        self.config = dict(config) if config is not None else {}
        self.expected_columns_ = list(_EXPECTED_COLUMNS)
        self.numeric_columns_ = list(_NUMERIC_MODEL)
        self.categorical_columns_ = list(_CATEGORICAL)
        self.numeric_medians_ = {}
        self.numeric_means_ = {}
        self.numeric_stds_ = {}
        self.encoder_ = None
        self.feature_names_out_ = None

    def _frame(self, X):
        if isinstance(X, pd.DataFrame):
            n = len(X)
            data = {}
            for col in self.expected_columns_:
                if col in X.columns:
                    data[col] = X[col].to_numpy(copy=True)
                else:
                    data[col] = np.full(n, np.nan, dtype=float)
            return pd.DataFrame(data, index=X.index)
        arr = np.asarray(X)
        if arr.ndim != 2 or arr.shape[1] != len(self.expected_columns_):
            raise ValueError('X must be a DataFrame or a 2D array with columns: ' + ', '.join(self.expected_columns_))
        return pd.DataFrame(arr, columns=self.expected_columns_)

    def _clean(self, X):
        df = self._frame(X)
        for col in _NUMERIC_BASE:
            arr = pd.to_numeric(df[col], errors='coerce').to_numpy(dtype=float, copy=True)
            arr[~np.isfinite(arr)] = np.nan
            df[col] = arr
        for col in ('x', 'y', 'z'):
            arr = df[col].to_numpy(dtype=float, copy=True)
            arr[arr == 0.0] = np.nan
            df[col] = arr
        arr = df['y'].to_numpy(dtype=float, copy=True)
        arr[arr > 10.0] = np.nan
        df['y'] = arr
        return df

    def _add_derived(self, df):
        carat = pd.to_numeric(df['carat'], errors='coerce').to_numpy(dtype=float, copy=True)
        carat[~np.isfinite(carat)] = np.nan
        df['carat'] = carat
        df['carat_power_2'] = carat * carat
        df['carat_power_3'] = carat * carat * carat
        return df

    def _categorical_frame(self, df):
        n = len(df)
        data = {}
        for col in self.categorical_columns_:
            if col in df.columns:
                raw = df[col].to_numpy(dtype=object, copy=True)
            else:
                raw = np.full(n, np.nan, dtype=object)
            values = np.empty(n, dtype=object)
            for i, value in enumerate(raw):
                values[i] = _MISSING_CATEGORY if pd.isna(value) else str(value)
            data[col] = values
        return pd.DataFrame(data, index=df.index)

    def fit_transform(self, X, y=None, context=None):
        df = self._clean(X)
        df = self._add_derived(df)
        self.numeric_medians_ = {}
        self.numeric_means_ = {}
        self.numeric_stds_ = {}
        for col in self.numeric_columns_:
            arr = df[col].to_numpy(dtype=float, copy=True)
            arr[~np.isfinite(arr)] = np.nan
            if np.all(np.isnan(arr)):
                median = 0.0
            else:
                median = float(np.nanmedian(arr))
            arr = np.where(np.isnan(arr), median, arr)
            mean = float(np.mean(arr)) if arr.size else 0.0
            std = float(np.std(arr, ddof=0)) if arr.size else 1.0
            if not np.isfinite(mean):
                mean = 0.0
            if not np.isfinite(std) or std == 0.0:
                std = 1.0
            self.numeric_medians_[col] = median
            self.numeric_means_[col] = mean
            self.numeric_stds_[col] = std
            df[col] = (arr - mean) / std
        self.encoder_ = OneHotEncoder(handle_unknown='ignore', sparse_output=False, dtype=np.float64)
        cat_arr = self.encoder_.fit_transform(self._categorical_frame(df))
        cat_names = list(self.encoder_.get_feature_names_out(self.categorical_columns_))
        self.feature_names_out_ = list(self.numeric_columns_) + cat_names
        num_arr = df[self.numeric_columns_].to_numpy(dtype=float)
        out = np.concatenate([num_arr, np.asarray(cat_arr, dtype=float)], axis=1)
        return np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)

    def transform(self, X):
        if self.encoder_ is None:
            raise RuntimeError('Preprocessor must be fitted before transform')
        df = self._clean(X)
        df = self._add_derived(df)
        for col in self.numeric_columns_:
            arr = df[col].to_numpy(dtype=float, copy=True)
            arr[~np.isfinite(arr)] = np.nan
            median = float(self.numeric_medians_.get(col, 0.0))
            arr = np.where(np.isnan(arr), median, arr)
            mean = float(self.numeric_means_.get(col, 0.0))
            std = float(self.numeric_stds_.get(col, 1.0))
            df[col] = (arr - mean) / std
        cat_arr = self.encoder_.transform(self._categorical_frame(df))
        num_arr = df[self.numeric_columns_].to_numpy(dtype=float)
        out = np.concatenate([num_arr, np.asarray(cat_arr, dtype=float)], axis=1)
        return np.nan_to_num(out, nan=0.0, posinf=0.0, neginf=0.0)

    def get_feature_names_out(self, input_features=None):
        return np.asarray(self.feature_names_out_, dtype=object)


def create_preprocessor(config):
    return Preprocessor(config)

MLMOM_PREPROCESSOR_V1 = True
